head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[content > P > alwaysDraw]<br/>컴포넌트가 렌더링될때 Content 도 함께 렌더링할지 설정합니다.",
    "validation" : [
        "alwaysDraw 속성 설정 시 TabControl 의 alwaysDraw 속성은 무시됩니다.",
        "미설정 시 TabControl 컴포넌트의 alwaysDraw 속성이 적용됩니다.",
        "true 설정 시 TabControl 컴포넌트가 렌더링될때 Content 를 함께 렌더링됩니다.",
        "false 설정 시 TabControl 컴포넌트가 렌더링될때 Content 가 함께 렌더링되지 않습니다.",
        "렌더링 되지 않은 Content 는 Tab 페이지가 선택되는 시점에 렌더링됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정   
    let properties = {
        alwaysDraw: con_alwaysDraw.getText(),
    };

    let cList = $c.gcm.createCList(properties);      
    let eList = $c.gcm.createEList(["onchange"]);

    let grp_comp = $c.gcm.getTestGroup();    
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    strTarget += '<w2:tabControl ' + strNameSpace + ' ' + eList + ' alwaysDraw="false" id="" style="width:500px;height:200px;">';
    strTarget += '<w2:tabs disabled="false" style="height:40px;" id="tabs1" label="Tabs1"></w2:tabs>';
    strTarget += '<w2:tabs disabled="false" style="height:40px" id="tabs2" label="Tabs2"></w2:tabs>';
    strTarget += '<w2:tabs disabled="false" style="height:40px" id="tabs3" label="Tabs3"></w2:tabs>';
    strTarget += '<w2:content style="height:160px;" id="content1">';
    strTarget += '<w2:button style="width:130px; height:50px;" id="content1_child" label="content1_child"></w2:button>';
    strTarget += '</w2:content>';
    strTarget += '<w2:content ' + cList + ' style="height:160px" id="content2">';
    strTarget += '<xf:input id="content2_child" style="width:144px; height:21px; " initValue="content2_child"></xf:input>';
    strTarget += '</w2:content>';
    strTarget += '<w2:content ' + cList + ' style="height:160px" id="content3">';
    strTarget += '<w2:textbox id="content3_child" label="content3_child" style="width:200px; height:50px; background-color:var(--ws-gray-300);"></w2:textbox>';
    strTarget += '</w2:content>';
    strTarget += '</w2:tabControl>';

    // target 생성
    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "tabControl",
        strTarget,
        grp_comp
    );

    scwin.btn_getContent_onclick();
}



scwin.btn_getContent_onclick = function (e) {
	let contentBody2 = document.querySelector('div[id*=target1_contents_content2_body]');

    if (contentBody2)
        wf_body_bottom.getObj("scwin").setReturnValue("Tabs2 의 content 렌더링 완료");
    else
        wf_body_bottom.getObj("scwin").setReturnValue("Tabs2 의 content 렌더링 미완료");

	let contentBody3 = document.querySelector('div[id*=target1_contents_content3_body]');

    if (contentBody3)
        wf_body_bottom.getObj("scwin").setReturnValue("Tabs3 의 content 렌더링 완료");
    else
        wf_body_bottom.getObj("scwin").setReturnValue("Tabs3 의 content 렌더링 미완료");
};



scwin.target1_onchange = function (tabId, index, userTabId) {
    scwin.btn_getContent_onclick();
}
